const asks=d.items.filter(x=>x.kind=="ask"),openAsks=asks.filter(x=>OPEN.includes(x.status)),tg=d.items.filter(x=>x.kind=="target"),rep=asks.reduce((a,x)=>a+(x.repeats||0),0);
